<script setup lang="ts">
import {ref,onMounted,inject,watch} from 'vue'
import {http} from '../api/http'
import Chart from './Chart.vue'
const data=ref<any>(),busy=ref(false),active=inject<any>('workspace-active',ref(true))
async function load(){busy.value=true;try{data.value=(await http.get('/dashboard/hr')).data}finally{busy.value=false}}
onMounted(load);watch(active,(v:boolean)=>{if(v)load()})
function pie(values:any[]){return {tooltip:{trigger:'item',formatter:'{b}: {c}人 ({d}%)'},legend:{bottom:0},series:[{type:'pie',radius:['38%','65%'],data:values,label:{formatter:'{b}\n{c}人'}}]}}
</script>
<template><section v-loading="busy"><el-button @click="load">更新看板</el-button><template v-if="data"><p class="v3-note">统计月份 {{data.month}} · {{data.notes}}</p><div class="v3-cards"><el-card>D01 · 当前在职人数<strong>{{data.active_employees}} 人</strong></el-card><el-card>D01 · 本月离职人数<strong>{{data.departed_this_month}} 人</strong></el-card><el-card>D04 · 本月出勤率<strong>{{data.attendance.current===null?'—':data.attendance.current+'%'}}</strong></el-card><el-card>D04 · 上月出勤率<strong>{{data.attendance.previous===null?'—':data.attendance.previous+'%'}}</strong><p>环比 {{data.attendance.difference===null?'—':data.attendance.difference+' 个百分点'}}</p></el-card></div><div class="v3-charts"><el-card><h3>D02 · 固定部门在职人数（人）</h3><Chart :option="pie(data.departments)"/></el-card><el-card><h3>D03 · 在职员工职级比例</h3><Chart :option="pie(data.grades)"/><p v-if="!data.grades.length" class="v3-note">暂无在职员工职级数据</p></el-card><el-card><h3>D05 · 本月获批请假工作日（天）</h3><Chart :option="{tooltip:{trigger:'axis'},xAxis:{type:'category',data:data.leave_days.map((d:any)=>d.name)},yAxis:{type:'value',minInterval:1},series:[{type:'bar',data:data.leave_days.map((d:any)=>d.value),itemStyle:{color:'#529076'}}]}"/></el-card><el-card><h3>D06 · 近六个月工资总额（元）</h3><Chart :option="{tooltip:{trigger:'axis'},grid:{left:70,right:20,bottom:40},xAxis:{type:'category',data:data.salaries.map((d:any)=>d.month)},yAxis:{type:'value'},series:[{type:'line',smooth:true,data:data.salaries.map((d:any)=>Number(d.amount)),itemStyle:{color:'#b49558'},areaStyle:{color:'#e7dcc2',opacity:0.3}}]}"/><p class="v3-note">按工资所属年月汇总；未录入月份为0，包含离职员工历史工资。</p></el-card></div></template></section></template>
